fn k_most_frequent(xs: List[Int], k: Int) -> List[(Int, Int)] {
  if k <= 0 {
    return []
  }
  return xs
    |> group_by(|x| x)
    |> map(|g| (g.0, len(g.1)))
    |> sort_by(|p| p.0)
    |> sort_desc_by(|p| p.1)
    |> take(k)
}

