fn max_subarray(xs: List[Int]) -> Option[(Int, Int, Int)] {
  var found = false
  var best_sum = 0
  var best_start = 0
  var best_end = 0
  for (i, _) in enumerate(xs) {
    var s = 0
    for (k, x) in enumerate(drop(xs, i)) {
      s = s + x
      if !found || s > best_sum {
        found = true
        best_sum = s
        best_start = i
        best_end = i + k
      }
    }
  }
  if found {
    return Some((best_sum, best_start, best_end))
  }
  return None
}

