  name: String,
  deps: List[String],
}

fn all_placed(deps: List[String], placed: List[String]) -> Bool {
  for d in deps {
    if !contains(placed, d) {
      return false
    }
  }
  return true
}

fn build_order(jobs: List[Job]) -> Result[List[String], String] {
  let names = map(jobs, |j| j.name)
  for (i, n) in enumerate(names) {
    if contains(take(names, i), n) {
      return Err("duplicate job: " + n)
    }
  }
  for j in jobs {
    for d in j.deps {
      if !contains(names, d) {
        return Err("unknown dependency: " + d)
      }
    }
  }
  var placed = take(names, 0)
  while len(placed) < len(jobs) {
    var found = false
    for j in jobs {
      if !contains(placed, j.name) && all_placed(j.deps, placed) {
        placed = append(placed, j.name)
        found = true
        break
      }
    }
    if !found {
      return Err("cycle detected")
    }
  }
  return Ok(placed)
}

