type Line {
  sku: String,
  qty: Int,
  unit_cents: Int,
}

fn floor_div(a: Int, b: Int) -> Int {
  let q = a / b
  if a % b != 0 && a < 0 {
    return q - 1
  }
  return q
}

fn line_amount(l: Line) -> Int {
  let amount = l.qty * l.unit_cents
  if l.qty >= 10 {
    return amount - floor_div(amount, 10)
  }
  return amount
}

fn apply_coupon(subtotal: Int, coupon: String) -> Result[Int, String] {
  if coupon == "" {
    return Ok(subtotal)
  } else if coupon == "SAVE500" {
    return Ok(max(subtotal - 500, 0))
  } else if coupon == "PCT10" {
    return Ok(subtotal - floor_div(subtotal, 10))
  } else if coupon == "BIG20" {
    if subtotal >= 10000 {
      return Ok(subtotal - floor_div(subtotal, 5))
    }
    return Err("coupon not applicable: BIG20")
  }
  return Err("unknown coupon: " + coupon)
}

fn invoice_total(lines: List[Line], coupon: String) -> Result[Int, String] {
  for l in lines {
    if l.qty < 1 {
      return Err("bad quantity: " + l.sku)
    }
  }
  var subtotal = 0
  for l in lines {
    subtotal = subtotal + line_amount(l)
  }
  let amount = try apply_coupon(subtotal, coupon)
  let tax = floor_div(amount * 8 + 50, 100)
  return Ok(amount + tax)
}

