fn alphabet() -> List[String] {
  return split("a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v,w,x,y,z", ",")
}

fn letter_at(idx: Int) -> String {
  let rest = drop(alphabet(), idx)
  return unwrap_or(first(rest), "")
}

fn shift_from(s: String, i: Int, k: Int) -> String {
  if i >= 26 {
    return s
  }
  let parts = split(s, letter_at(i))
  let shifted_parts = map(parts, |p| shift_from(p, i + 1, k))
  let target = (k % 26 + 26 + i) % 26
  return join(shifted_parts, letter_at(target))
}

fn caesar_shift(s: String, k: Int) -> String {
  return shift_from(s, 0, k)
}

