from __future__ import annotations
from typing import Callable, Generic, Literal, TypedDict, TypeVar

T = TypeVar("T")

class Ok(TypedDict, Generic[T]):
    ok: Literal[True]
    value: T

class Err(TypedDict):
    ok: Literal[False]
    error: str

class Job(TypedDict):
    name: str
    deps: list[str]


import heapq


def _err(msg: str) -> Err:
    e: Err = {"ok": False, "error": msg}
    return e


def build_order(jobs: list[Job]) -> Ok[list[str]] | Err:
    index: dict[str, int] = {}
    for i, job in enumerate(jobs):
        name = job["name"]
        if name in index:
            return _err("duplicate job: " + name)
        index[name] = i

    for job in jobs:
        for d in job["deps"]:
            if d not in index:
                return _err("unknown dependency: " + d)

    n = len(jobs)
    remaining: list[int] = [0] * n
    dependents: list[list[int]] = [[] for _ in range(n)]
    for i, job in enumerate(jobs):
        unique = set(job["deps"])
        remaining[i] = len(unique)
        for d in unique:
            dependents[index[d]].append(i)

    heap: list[int] = [i for i in range(n) if remaining[i] == 0]
    heapq.heapify(heap)
    order: list[str] = []
    while heap:
        i = heapq.heappop(heap)
        order.append(jobs[i]["name"])
        for j in dependents[i]:
            remaining[j] -= 1
            if remaining[j] == 0:
                heapq.heappush(heap, j)

    if len(order) != n:
        return _err("cycle detected")
    result: Ok[list[str]] = {"ok": True, "value": order}
    return result

