  let syms = ["X", "O", "."]
  var out = None
  for a in syms {
    for b in syms {
      for c in syms {
        if a + b + c == row {
          out = Some([a, b, c])
        }
      }
    }
  }
  return out
}

fn cell_at(cells: List[String], i: Int) -> String {
  return cells
    |> drop(i)
    |> first()
    |> unwrap_or(".")
}

fn has_line(cells: List[String], p: String) -> Bool {
  let lines = [
    (0, 1, 2),
    (3, 4, 5),
    (6, 7, 8),
    (0, 3, 6),
    (1, 4, 7),
    (2, 5, 8),
    (0, 4, 8),
    (2, 4, 6),
  ]
  var found = false
  for l in lines {
    if cell_at(cells, l.0) == p && cell_at(cells, l.1) == p && cell_at(cells, l.2) == p {
      found = true
      break
    }
  }
  return found
}

fn count_of(cells: List[String], p: String) -> Int {
  return len(filter(cells, |c| c == p))
}

fn tic_tac_toe(board: List[String]) -> String {
  if len(board) != 3 {
    return "invalid"
  }
  var cells = take(["."], 0)
  var bad = false
  for row in board {
    let rc = row_cells(row)
    if rc == None {
      bad = true
    }
    for c in unwrap_or(rc, take(["."], 0)) {
      cells = append(cells, c)
    }
  }
  if bad {
    return "invalid"
  }
  let xs = count_of(cells, "X")
  let os = count_of(cells, "O")
  if !(xs == os || xs == os + 1) {
    return "invalid"
  }
  let xw = has_line(cells, "X")
  let ow = has_line(cells, "O")
  if xw && ow {
    return "invalid"
  }
  if xw && xs != os + 1 {
    return "invalid"
  }
  if ow && xs != os {
    return "invalid"
  }
  if xw {
    return "X wins"
  }
  if ow {
    return "O wins"
  }
  if xs + os == 9 {
    return "draw"
  }
  return "in progress"
}

