export function caesar_shift(s: string, k: number): string {
  const shift = ((Math.trunc(k) % 26) + 26) % 26;
  let out = "";
  for (const ch of s) {
    const code = ch.charCodeAt(0);
    if (ch.length === 1 && code >= 97 && code <= 122) {
      out += String.fromCharCode(((code - 97 + shift) % 26) + 97);
    } else {
      out += ch;
    }
  }
  return out;
}

