from __future__ import annotations
from typing import Callable, Generic, Literal, TypedDict, TypeVar

class Insert(TypedDict):
    kind: Literal["Insert"]
    text: str

class Delete(TypedDict):
    kind: Literal["Delete"]
    n: int

class Left(TypedDict):
    kind: Literal["Left"]
    n: int

class Right(TypedDict):
    kind: Literal["Right"]
    n: int

class Undo(TypedDict):
    kind: Literal["Undo"]

EditOp = Insert | Delete | Left | Right | Undo


def text_editor(ops: list[EditOp]) -> str:
    text = ""
    cursor = 0
    history: list[tuple[str, int]] = []
    for op in ops:
        if op["kind"] == "Insert":
            history.append((text, cursor))
            t = op["text"]
            text = text[:cursor] + t + text[cursor:]
            cursor += len(t)
        elif op["kind"] == "Delete":
            history.append((text, cursor))
            k = min(op["n"], cursor)
            text = text[: cursor - k] + text[cursor:]
            cursor -= k
        elif op["kind"] == "Left":
            cursor = max(0, cursor - op["n"])
        elif op["kind"] == "Right":
            cursor = min(len(text), cursor + op["n"])
        else:
            if history:
                text, cursor = history.pop()
    return text

