    os_ = sum(row.count("O") for row in board)
    if not (xs == os_ or xs == os_ + 1):
        return "invalid"
    xw = _has_line(board, "X")
    ow = _has_line(board, "O")
    if xw and ow:
        return "invalid"
    if xw:
        return "X wins" if xs == os_ + 1 else "invalid"
    if ow:
        return "O wins" if xs == os_ else "invalid"
    if all("." not in row for row in board):
        return "draw"
    return "in progress"

