type Job = { name: string; deps: string[] };
type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function build_order(jobs: Job[]): Result<string[]> {
  const names = new Set<string>();
  for (const job of jobs) {
    if (names.has(job.name)) {
      return { ok: false, error: "duplicate job: " + job.name };
    }
    names.add(job.name);
  }

  for (const job of jobs) {
    for (const dep of job.deps) {
      if (!names.has(dep)) {
        return { ok: false, error: "unknown dependency: " + dep };
      }
    }
  }

  const placed = new Set<string>();
  const done: boolean[] = jobs.map(() => false);
  const order: string[] = [];
  while (order.length < jobs.length) {
    let picked = -1;
    for (let i = 0; i < jobs.length; i++) {
      if (done[i]) continue;
      const job = jobs[i];
      if (job.deps.every((d) => placed.has(d))) {
        picked = i;
        break;
      }
    }
    if (picked === -1) {
      return { ok: false, error: "cycle detected" };
    }
    done[picked] = true;
    placed.add(jobs[picked].name);
    order.push(jobs[picked].name);
  }
  return { ok: true, value: order };
}

