from __future__ import annotations
from typing import Callable, Generic, Literal, TypedDict, TypeVar

T = TypeVar("T")

class Ok(TypedDict, Generic[T]):
    ok: Literal[True]
    value: T

class Err(TypedDict):
    ok: Literal[False]
    error: str

class Push(TypedDict):
    kind: Literal["Push"]
    n: int

class Pop(TypedDict):
    kind: Literal["Pop"]

class Add(TypedDict):
    kind: Literal["Add"]

class Sub(TypedDict):
    kind: Literal["Sub"]

class Mul(TypedDict):
    kind: Literal["Mul"]

class Dup(TypedDict):
    kind: Literal["Dup"]

class Swap(TypedDict):
    kind: Literal["Swap"]

class Jz(TypedDict):
    kind: Literal["Jz"]
    target: int

class Jmp(TypedDict):
    kind: Literal["Jmp"]
    target: int

class Print(TypedDict):
    kind: Literal["Print"]

class Halt(TypedDict):
    kind: Literal["Halt"]

Instr = Push | Pop | Add | Sub | Mul | Dup | Swap | Jz | Jmp | Print | Halt


def _err(msg: str) -> Err:
    e: Err = {"ok": False, "error": msg}
    return e


_NEEDS: dict[str, int] = {
    "Pop": 1, "Dup": 1, "Print": 1, "Jz": 1,
    "Add": 2, "Sub": 2, "Mul": 2, "Swap": 2,
}


def stack_vm(prog: list[Instr]) -> Ok[list[int]] | Err:
    stack: list[int] = []
    out: list[int] = []
    pc = 0
    steps = 0
    n = len(prog)
    while 0 <= pc < n:
        if steps >= 1000:
            return _err("step limit exceeded")
        steps += 1
        ins = prog[pc]
        kind = ins["kind"]
        if len(stack) < _NEEDS.get(kind, 0):
            return _err(f"stack underflow at {pc}")
        nxt = pc + 1
        if ins["kind"] == "Push":
            stack.append(ins["n"])
        elif ins["kind"] == "Pop":
            stack.pop()
        elif ins["kind"] in ("Add", "Sub", "Mul"):
            b = stack.pop()
            a = stack.pop()
            if kind == "Add":
                stack.append(a + b)
            elif kind == "Sub":
                stack.append(a - b)
            else:
                stack.append(a * b)
        elif ins["kind"] == "Dup":
            stack.append(stack[-1])
        elif ins["kind"] == "Swap":
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif ins["kind"] == "Print":
            out.append(stack.pop())
        elif ins["kind"] == "Jz":
            v = stack.pop()
            t = ins["target"]
            if not (0 <= t < n):
                return _err(f"bad jump at {pc}")
            if v == 0:
                nxt = t
        elif ins["kind"] == "Jmp":
            t = ins["target"]
            if not (0 <= t < n):
                return _err(f"bad jump at {pc}")
            nxt = t
        else:
            break
        pc = nxt
    res: Ok[list[int]] = {"ok": True, "value": out}
    return res

