type EditOp =
  | Insert(text: String)
  | Delete(n: Int)
  | Left(n: Int)
  | Right(n: Int)
  | Undo

type Snap {
  chars: List[String],
  cursor: Int,
}

type State {
  chars: List[String],
  cursor: Int,
  history: List[Snap],
}

fn chars_of(s: String) -> List[String] {
  return filter(split(s, ""), |c| c != "")
}

fn concat(xs: List[String], ys: List[String]) -> List[String] {
  return fold(ys, xs, |acc, y| append(acc, y))
}

fn snap_of(st: State) -> Snap {
  return Snap { chars: st.chars, cursor: st.cursor }
}

fn do_insert(st: State, t: String) -> State {
  let ins = chars_of(t)
  let before = take(st.chars, st.cursor)
  let after = drop(st.chars, st.cursor)
  let joined = concat(concat(before, ins), after)
  let hist = append(st.history, snap_of(st))
  return State { chars: joined, cursor: st.cursor + len(ins), history: hist }
}

fn do_delete(st: State, n: Int) -> State {
  let k = min(n, st.cursor)
  let before = take(st.chars, st.cursor - k)
  let after = drop(st.chars, st.cursor)
  let hist = append(st.history, snap_of(st))
  return State { chars: concat(before, after), cursor: st.cursor - k, history: hist }
}

fn do_undo(st: State) -> State {
  return match last(st.history) {
    Some(s) => State { chars: s.chars, cursor: s.cursor, history: take(st.history, len(st.history) - 1) },
    None => st,
  }
}

fn step(st: State, op: EditOp) -> State {
  return match op {
    Insert(t) => do_insert(st, t),
    Delete(n) => do_delete(st, n),
    Left(n) => State { chars: st.chars, cursor: max(0, st.cursor - n), history: st.history },
    Right(n) => State { chars: st.chars, cursor: min(len(st.chars), st.cursor + n), history: st.history },
    Undo => do_undo(st),
  }
}

fn text_editor(ops: List[EditOp]) -> String {
  var st = State { chars: [], cursor: 0, history: [] }
  for op in ops {
    st = step(st, op)
  }
  return join(st.chars, "")
}

