type Result<T> = { ok: true; value: T } | { ok: false; error: string };

const UNIT_SECONDS: Record<string, number> = { h: 3600, m: 60, s: 1 };
const UNIT_ORDER: Record<string, number> = { h: 0, m: 1, s: 2 };

export function parse_duration(s: string): Result<number> {
  if (s.length === 0) {
    return { ok: false, error: "empty" };
  }
  let total = 0;
  let digits = "";
  let lastOrder = -1;
  for (const ch of s) {
    if (ch >= "0" && ch <= "9") {
      digits += ch;
      continue;
    }
    if (!(ch in UNIT_SECONDS)) {
      return { ok: false, error: `unknown unit: ${ch}` };
    }
    if (digits.length === 0) {
      return { ok: false, error: `missing number before ${ch}` };
    }
    const order = UNIT_ORDER[ch];
    if (order <= lastOrder) {
      return { ok: false, error: `unit out of order: ${ch}` };
    }
    lastOrder = order;
    total += parseInt(digits, 10) * UNIT_SECONDS[ch];
    digits = "";
  }
  if (digits.length > 0) {
    return { ok: false, error: "missing unit" };
  }
  return { ok: true, value: total };
}

