type Line = { sku: string; qty: number; unit_cents: number };
type Result<T> = { ok: true; value: T } | { ok: false; error: string };

function floorDiv(a: bigint, b: bigint): bigint {
  const q = a / b;
  const r = a % b;
  if (r !== 0n && (r < 0n) !== (b < 0n)) {
    return q - 1n;
  }
  return q;
}

export function invoice_total(lines: Line[], coupon: string): Result<number> {
  for (const line of lines) {
    if (line.qty < 1) {
      return { ok: false, error: "bad quantity: " + line.sku };
    }
  }

  let subtotal = 0n;
  for (const line of lines) {
    const qty = BigInt(line.qty);
    let amount = qty * BigInt(line.unit_cents);
    if (line.qty >= 10) {
      amount -= floorDiv(amount, 10n);
    }
    subtotal += amount;
  }

  let amount: bigint;
  if (coupon === "") {
    amount = subtotal;
  } else if (coupon === "SAVE500") {
    amount = subtotal - 500n;
    if (amount < 0n) {
      amount = 0n;
    }
  } else if (coupon === "PCT10") {
    amount = subtotal - floorDiv(subtotal, 10n);
  } else if (coupon === "BIG20") {
    if (subtotal < 10000n) {
      return { ok: false, error: "coupon not applicable: BIG20" };
    }
    amount = subtotal - floorDiv(subtotal, 5n);
  } else {
    return { ok: false, error: "unknown coupon: " + coupon };
  }

  const tax = floorDiv(amount * 8n + 50n, 100n);
  return { ok: true, value: Number(amount + tax) };
}

