initial:
type Instr =
  | Push(n: Int)
  | Pop
  | Add
  | Sub
  | Mul
  | Dup
  | Swap
  | Jz(target: Int)
  | Jmp(target: Int)
  | Print
  | Halt

fn top(st: List[Int]) -> Int {
  return unwrap_or(last(st), 0)
}

fn pop1(st: List[Int]) -> List[Int] {
  if len(st) == 0 {
    return st
  }
  return take(st, len(st) - 1)
}

fn jz_target(b: Int, t: Int, pc: Int) -> Int {
  if b == 0 {
    return t
  }
  return pc + 1
}

fn step(
  ins: Instr,
  pc: Int,
  stack: List[Int],
  out: List[Int],
  n: Int,
) -> Result[(Int, List[Int], List[Int]), String] {
  let need = match ins {
    Pop => 1,
    Dup => 1,
    Print => 1,
    Jz(_) => 1,
    Add => 2,
    Sub => 2,
    Mul => 2,
    Swap => 2,
    _ => 0,
  }
  if len(stack) < need {
    return Err("stack underflow at " + to_string(pc))
  }
  let tgt = match ins {
    Jz(t) => t,
    Jmp(t) => t,
    _ => 0,
  }
  let is_jump = match ins {
    Jz(_) => true,
    Jmp(_) => true,
    _ => false,
  }
  if is_jump && (tgt < 0 || tgt >= n) {
    return Err("bad jump at " + to_string(pc))
  }
  let b = top(stack)
  let rest1 = pop1(stack)
  let a = top(rest1)
  let rest2 = pop1(rest1)
  return Ok(match ins {
    Push(v) => (pc + 1, append(stack, v), out),
    Pop => (pc + 1, rest1, out),
    Add => (pc + 1, append(rest2, a + b), out),
    Sub => (pc + 1, append(rest2, a - b), out),
    Mul => (pc + 1, append(rest2, a * b), out),
    Dup => (pc + 1, append(stack, b), out),
    Swap => (pc + 1, append(append(rest2, b), a), out),
    Jz(t) => (jz_target(b, t, pc), rest1, out),
    Jmp(t) => (t, stack, out),
    Print => (pc + 1, rest1, append(out, b)),
