export function max_subarray(xs: number[]): [number, number, number] | null {
  if (xs.length === 0) {
    return null;
  }
  let cur = xs[0];
  let curStart = 0;
  let best = xs[0];
  let bestStart = 0;
  let bestEnd = 0;
  for (let j = 1; j < xs.length; j++) {
    const x = xs[j];
    if (cur >= 0) {
      cur += x;
    } else {
      cur = x;
      curStart = j;
    }
    if (cur > best || (cur === best && curStart < bestStart)) {
      best = cur;
      bestStart = curStart;
      bestEnd = j;
    }
  }
  return [best, bestStart, bestEnd];
}

