type EditOp =
  | { kind: "Insert"; text: string }
  | { kind: "Delete"; n: number }
  | { kind: "Left"; n: number }
  | { kind: "Right"; n: number }
  | { kind: "Undo" };

export function text_editor(ops: EditOp[]): string {
  let text = "";
  let cursor = 0;
  const history: Array<[string, number]> = [];
  for (const op of ops) {
    switch (op.kind) {
      case "Insert": {
        history.push([text, cursor]);
        text = text.slice(0, cursor) + op.text + text.slice(cursor);
        cursor += op.text.length;
        break;
      }
      case "Delete": {
        history.push([text, cursor]);
        const k = Math.min(op.n, cursor);
        text = text.slice(0, cursor - k) + text.slice(cursor);
        cursor -= k;
        break;
      }
      case "Left": {
        cursor = Math.max(0, cursor - op.n);
        break;
      }
      case "Right": {
        cursor = Math.min(text.length, cursor + op.n);
        break;
      }
      case "Undo": {
        const prev = history.pop();
        if (prev !== undefined) {
          text = prev[0];
          cursor = prev[1];
        }
        break;
      }
    }
  }
  return text;
}

