function hasLine(board: string[], p: string): boolean {
  const at = (r: number, c: number): string => (board[r] ?? "").charAt(c);
  for (let i = 0; i < 3; i++) {
    if (at(i, 0) === p && at(i, 1) === p && at(i, 2) === p) return true;
    if (at(0, i) === p && at(1, i) === p && at(2, i) === p) return true;
  }
  if (at(0, 0) === p && at(1, 1) === p && at(2, 2) === p) return true;
  if (at(0, 2) === p && at(1, 1) === p && at(2, 0) === p) return true;
  return false;
}

export function tic_tac_toe(board: string[]): string {
  let x = 0;
  let o = 0;
  let empty = 0;
  for (let r = 0; r < 3; r++) {
    const row = board[r] ?? "";
    for (let c = 0; c < 3; c++) {
      const ch = row.charAt(c);
      if (ch === "X") x++;
      else if (ch === "O") o++;
      else empty++;
    }
  }
  if (!(x === o || x === o + 1)) return "invalid";
  const xw = hasLine(board, "X");
  const ow = hasLine(board, "O");
  if (xw && ow) return "invalid";
  if (xw && x !== o + 1) return "invalid";
  if (ow && x !== o) return "invalid";
  if (xw) return "X wins";
  if (ow) return "O wins";
  if (empty === 0) return "draw";
  return "in progress";
}

