type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function parse_money(s: string): Result<number> {
  let i = 0;
  let neg = false;
  if (s[0] === "-") {
    neg = true;
    i = 1;
  }
  if (s[i] !== "$") {
    return { ok: false, error: "missing $" };
  }
  const rest = s.slice(i + 1);
  const dot = rest.indexOf(".");
  let dollarsStr = rest;
  let cents = 0;
  if (dot >= 0) {
    const centsStr = rest.slice(dot + 1);
    if (!/^[0-9]{2}$/.test(centsStr)) {
      return { ok: false, error: "bad cents" };
    }
    cents = Number(centsStr);
    dollarsStr = rest.slice(0, dot);
  }
  if (!/^[0-9]+$/.test(dollarsStr) && !/^[0-9]{1,3}(,[0-9]{3})+$/.test(dollarsStr)) {
    return { ok: false, error: "bad dollars" };
  }
  const digits = dollarsStr.replace(/,/g, "");
  if (digits.length > 1 && digits[0] === "0") {
    return { ok: false, error: "bad dollars" };
  }
  const v = Number(digits) * 100 + cents;
  return { ok: true, value: neg && v !== 0 ? -v : v };
}

