initial:
type Instr =
  | { kind: "Push"; n: number }
  | { kind: "Pop" }
  | { kind: "Add" }
  | { kind: "Sub" }
  | { kind: "Mul" }
  | { kind: "Dup" }
  | { kind: "Swap" }
  | { kind: "Jz"; target: number }
  | { kind: "Jmp"; target: number }
  | { kind: "Print" }
  | { kind: "Halt" };
type Result<T> = { ok: true; value: T } | { ok: false; error: string };

function needs(ins: Instr): number {
  switch (ins.kind) {
    case "Pop":
    case "Dup":
    case "Print":
    case "Jz":
      return 1;
    case "Add":
    case "Sub":
    case "Mul":
    case "Swap":
      return 2;
    default:
      return 0;
  }
}

export function stack_vm(prog: Instr[]): Result<number[]> {
  const stack: number[] = [];
  const out: number[] = [];
  let pc = 0;
  let steps = 0;
  while (pc >= 0 && pc < prog.length) {
    if (steps >= 1000) return { ok: false, error: "step limit exceeded" };
    steps++;
    const ins = prog[pc];
    if (stack.length < needs(ins)) {
      return { ok: false, error: `stack underflow at ${pc}` };
    }
    switch (ins.kind) {
      case "Push":
        stack.push(ins.n);
        pc++;
        break;
      case "Pop":
        stack.pop();
        pc++;
        break;
      case "Add":
      case "Sub":
      case "Mul": {
        const b = stack.pop() as number;
        const a = stack.pop() as number;
        stack.push(ins.kind === "Add" ? a + b : ins.kind === "Sub" ? a - b : a * b);
        pc++;
        break;
      }
      case "Dup":
        stack.push(stack[stack.length - 1]);
        pc++;
        break;
      case "Swap": {
        const n = stack.length;
        const t = stack[n - 1];
        stack[n - 1] = stack[n - 2];
        stack[n - 2] = t;
        pc++;
        break;
      }
      case "Print":
        out.push(stack.pop() as number);
        pc++;
        break;
      case "Jz": {
        const v = stack.pop() as number;
        if (!Number.isInteger(ins.target) || ins.target < 0 || ins.target >= prog.length) {
          return { ok: false, error: `bad jump at ${pc}` };
        }
        pc = v === 0 ? ins.target : pc + 1;
        break;
      }
      case "Jmp":
        if (!Number.isInteger(ins.target) || ins.target < 0 || ins.target >= prog.length) {
          return { ok: false, error: `bad jump at ${pc}` };
        }
        pc = ins.target;
        break;
      case "Halt":
        return { ok: true, value: out };
    }
  }
  return { ok: true, value: out };
}

